package com.bank.inquiry.controller;

import com.bank.inquiry.dto.*;
import com.bank.inquiry.service.AccountService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.List;

@RestController
@RequestMapping("/api/v1/accounts")
@RequiredArgsConstructor
public class AccountController {

    private final AccountService accountService;

    @GetMapping("/{id}")
    public AccountSummary get(@PathVariable String id) { return accountService.getAccount(id); }

    @GetMapping("/type/{type}")
    public List<AccountSummary> getByType(@PathVariable String type) { return accountService.getByType(type); }

    @GetMapping("/high-balance")
    public List<AccountSummary> highBalance(@RequestParam BigDecimal min) { return accountService.getHighBalance(min); }

    @GetMapping("/count/active")
    public long countActive() { return accountService.countActive(); }

    @PostMapping("/deposit")
    public AccountSummary deposit(@RequestBody @Valid DepositRequest request) { return accountService.deposit(request); }

    @PostMapping("/{id}/withdraw")
    public AccountSummary withdraw(@PathVariable String id, @RequestParam BigDecimal amount) {
        return accountService.withdraw(id, amount);
    }
}
