package com.bank.inquiry.service;

import com.bank.inquiry.dto.*;
import com.bank.inquiry.model.Account;
import com.bank.inquiry.repository.AccountRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.math.BigDecimal;
import java.util.Optional;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class AccountServiceTest {

    @Mock AccountRepository accountRepo;
    @InjectMocks AccountService accountService;

    @Test
    void shouldReturnAccountSummary() {
        Account acc = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        when(accountRepo.findById("SAV2001")).thenReturn(Optional.of(acc));

        AccountSummary summary = accountService.getAccount("SAV2001");

        assertThat(summary.accountId()).isEqualTo("SAV2001");
        assertThat(summary.balance()).isEqualByComparingTo("1000000");
    }

    @Test
    void shouldDepositSuccessfully() {
        Account acc = new Account("SAV2001", "Rajesh", new BigDecimal("1000000"));
        when(accountRepo.findById("SAV2001")).thenReturn(Optional.of(acc));
        when(accountRepo.save(any())).thenAnswer(i -> i.getArgument(0));

        AccountSummary result = accountService.deposit(new DepositRequest("SAV2001", new BigDecimal("50000")));

        assertThat(result.balance()).isEqualByComparingTo("1050000");
    }
}
